class Exporter(ABC):
    @abstractmethod
    def export(self, rows): ...

class CsvExporter(Exporter):
    def export(self, rows):
        return to_csv(rows)

class ExporterFactory:
    _registry = {"csv": CsvExporter}

    @classmethod
    def create(cls, kind, **opts):
        return cls._registry[kind](**opts)

def export_orders(rows, kind="csv", retries=0, hooks=None, formatter=None):
    exporter = ExporterFactory.create(kind)
    return exporter.export(rows)
